void draw_arrow(VkCommandBuffer cmd, const linalg::vec3 &start,
                const linalg::vec3 &end, color_t color)
{
  using namespace linalg;

  vec3 dir = end - start;
  float len = length(dir);
  if (len < 0.0001f)
    return;

  vec3 w = dir * (1.0f / len);

  // Find arbitrary up vector
  vec3 up = {{0, 1, 0}};
  if (std::abs(dot(w, up)) > 0.99f)
  {
    up = {{1, 0, 0}};
  }

  vec3 u = normalize(cross(up, w));
  vec3 v = cross(w, u);

  float head_len = 0.5f;
  float head_width = 0.2f;
  float shaft_width = 0.05f;

  if (len < head_len)
  {
    head_len = len; // Arrow is just head if too short
  }

  vec3 shaft_end = start + w * (len - head_len);

  // -- Draw Shaft (AABB-like Box) --
  // If we really want an "AABB" as the user asked ("from an AABB"),
  // we align it with the arrow frame. It's an OBB really.
  if (len > head_len)
  {
    float sw = shaft_width * 0.5f;
    vec3 c1 = start - u * sw - v * sw;
    vec3 c2 = start + u * sw - v * sw;
    vec3 c3 = start + u * sw + v * sw;
    vec3 c4 = start - u * sw + v * sw;

    vec3 c5 = shaft_end - u * sw - v * sw;
    vec3 c6 = shaft_end + u * sw - v * sw;
    vec3 c7 = shaft_end + u * sw + v * sw;
    vec3 c8 = shaft_end - u * sw + v * sw;

    // Base
    draw_line(cmd, c1, c2, color);
    draw_line(cmd, c2, c3, color);
    draw_line(cmd, c3, c4, color);
    draw_line(cmd, c4, c1, color);

    // Top
    draw_line(cmd, c5, c6, color);
    draw_line(cmd, c6, c7, color);
    draw_line(cmd, c7, c8, color);
    draw_line(cmd, c8, c5, color);

    // Sides
    draw_line(cmd, c1, c5, color);
    draw_line(cmd, c2, c6, color);
    draw_line(cmd, c3, c7, color);
    draw_line(cmd, c4, c8, color);
  }

  // -- Draw Head (Pyramid) --
  {
    float hw = head_width * 0.5f;
    vec3 b1 = shaft_end - u * hw - v * hw;
    vec3 b2 = shaft_end + u * hw - v * hw;
    vec3 b3 = shaft_end + u * hw + v * hw;
    vec3 b4 = shaft_end - u * hw + v * hw;

    // Base
    draw_line(cmd, b1, b2, color);
    draw_line(cmd, b2, b3, color);
    draw_line(cmd, b3, b4, color);
    draw_line(cmd, b4, b1, color);

    // Tip
    draw_line(cmd, b1, end, color);
    draw_line(cmd, b2, end, color);
    draw_line(cmd, b3, end, color);
    draw_line(cmd, b4, end, color);
  }
}

void draw_wedge(VkCommandBuffer cmd, const shared::wedge_t &wedge,
                color_t color)
{
  auto points = shared::get_wedge_points(wedge);

  // Draw Base Loop (0-1-2-3)
  draw_line(cmd, points[0], points[1], color);
  draw_line(cmd, points[1], points[2], color);
  draw_line(cmd, points[2], points[3], color);
  draw_line(cmd, points[3], points[0], color);

  // Draw Top Edge (4-5)
  draw_line(cmd, points[4], points[5], color);

  // Connect Top Edge to Base
  const float epsilon = 0.001f;
  linalg::vec3 edge_delta = points[5] - points[4];
  bool edge_along_x = std::abs(edge_delta.x) > std::abs(edge_delta.z);

  for (int i = 4; i <= 5; ++i)
  {
    linalg::vec3 top = points[i];
    for (int j = 0; j < 4; ++j)
    {
      linalg::vec3 base = points[j];
      bool share_x = std::abs(top.x - base.x) < epsilon;
      bool share_z = std::abs(top.z - base.z) < epsilon;

      if (edge_along_x)
      {
        // Edge along X -> Slope along Z. Connect if Share X.
        if (share_x)
          draw_line(cmd, top, base, color);
      }
      else
      {
        // Edge along Z -> Slope along X. Connect if Share Z.
        if (share_z)
          draw_line(cmd, top, base, color);
      }
    }
  }
}

// Debug hitbox shapes are LINE primitives, not wireframe-mode meshes. The mesh
// path needed the Sphere/Cylinder assets to resolve AND the device to support
// fillModeNonSolid, and draw_mesh returns silently when either is missing --
// so on a device without it the head hitbox simply never appeared. Lines go
// through the same batch as every other debug draw and have no such dependency.

// One circle of `segment_count` segments on the plane spanned by `axis_u` and
// `axis_v`, both expected to be unit vectors.
static void draw_circle(VkCommandBuffer cmd, const linalg::vec3 &center,
                        const linalg::vec3 &axis_u, const linalg::vec3 &axis_v,
                        float radius, color_t color, int segment_count)
{
  linalg::vec3 previous = center + axis_u * radius;
  for (int segment = 1; segment <= segment_count; ++segment)
  {
    const float angle = (2.0f * 3.14159265f * segment) / segment_count;
    const linalg::vec3 current =
        center + axis_u * (std::cos(angle) * radius) + axis_v * (std::sin(angle) * radius);
    draw_line(cmd, previous, current, color);
    previous = current;
  }
}

void draw_hitbox_sphere(VkCommandBuffer cmd, const linalg::vec3 &center,
                        float radius, color_t color)
{
  constexpr int SEGMENTS = 20;
  const linalg::vec3 x{1, 0, 0};
  const linalg::vec3 y{0, 1, 0};
  const linalg::vec3 z{0, 0, 1};

  // Three great circles — enough to read as a sphere from any angle.
  draw_circle(cmd, center, x, z, radius, color, SEGMENTS); // horizontal
  draw_circle(cmd, center, x, y, radius, color, SEGMENTS); // vertical, facing Z
  draw_circle(cmd, center, z, y, radius, color, SEGMENTS); // vertical, facing X
}

void draw_hitbox_capsule(VkCommandBuffer cmd, const linalg::vec3 &center,
                         float radius, float half_height, color_t color)
{
  constexpr int SEGMENTS = 20;
  const linalg::vec3 x{1, 0, 0};
  const linalg::vec3 z{0, 0, 1};

  // `center` is the middle of the capsule; half_height is the CYLINDER half,
  // so the caps sit at +/- half_height and the total height is
  // 2 * (half_height + radius).
  const linalg::vec3 top{center.x, center.y + half_height, center.z};
  const linalg::vec3 bottom{center.x, center.y - half_height, center.z};

  draw_circle(cmd, top, x, z, radius, color, SEGMENTS);
  draw_circle(cmd, bottom, x, z, radius, color, SEGMENTS);

  // Four side lines at the cardinal points.
  for (const linalg::vec3 &offset : {linalg::vec3{radius, 0, 0}, linalg::vec3{-radius, 0, 0},
                                     linalg::vec3{0, 0, radius}, linalg::vec3{0, 0, -radius}})
    draw_line(cmd, bottom + offset, top + offset, color);

  // Full spheres for the caps rather than hemispheres — the extra half is
  // inside the cylinder, which reads fine and keeps this short.
  draw_hitbox_sphere(cmd, top, radius, color);
  draw_hitbox_sphere(cmd, bottom, radius, color);
}

